tests.pseudocode:
want := []string{"read_file", "list_files", "find_files", "search_files", "file_outline", "find_symbol", "find_references"}
assert slices.Equal(agentrun.ReadOnlyFileTools, want)
assert len(agentrun.ReadOnlyFileTools) == 7

p := faux.New(textTurn("done"))
ws := newWorkspace(t)
r := newRunner(fauxConfig(p, ws))
phase := agentrun.Phase{Name: "test", System: "s", User: "u", BuiltinTools: agentrun.ReadOnlyFileTools, ReadOnly: true, Custom: []core.Tool{submitTool(...)}, Terminator: "submit"}
r.Run(ctx, phase)
req := p.Requests()[0]
declared := map[string]bool{}
for _, tool := range req.Tools { declared[tool.Name] = true }
for _, n := range agentrun.ReadOnlyFileTools { assert declared[n], n + " missing" }

assert strings.Contains(repomap.Intro, "find_references")
assert strings.Contains(repomap.Intro, "calls") || strings.Contains(repomap.Intro, "uses")
for _, name := range []string{"read_file", "file_outline", "find_symbol", "find_files", "search_files"} {
  assert strings.Contains(repomap.Intro, name)
}

p := faux.New(toolCallTurn("c1", "submit_survey", validSurvey()))
b := &agentBrain{runner: newRunner(fauxConfig(p, ws))}
b.Survey(ctx, surveyInput{...})
req := p.Requests()[0]
declared := toolNames(req)
for _, n := range agentrun.ReadOnlyFileTools { assert declared[n] }

p := faux.New()
a := &agentAuthor{runner: newRunner(fauxConfig(p, ws)), ws: ws}
a.WritePRD(ctx, prdRequest{...})
got := wireTools(t, p)
for _, n := range agentrun.ReadOnlyFileTools { assert got[n] }

for n := 0; n <= 20; n++ {
  grant := make([]string, n)
  for i := range grant { grant[i] = fmt.Sprintf("tool_%d", i) }
  orig := slices.Clone(grant)
  result := agentrun.WithCodeSearch(grant, true)
  assert slices.Equal(grant, orig)
  assert len(result) == n+1
  assert result[len(result)-1] == "code_search"
}
